import asyncio
import logging
import uuid
from dataclasses import dataclass
from typing import Any, Dict, Optional, Text

import aiohttp
from sanic import Blueprint, response
from sanic.request import Request
from sanic.response import HTTPResponse

import rasa.utils.endpoints
from rasa.core.channels.channel import (
    CollectingOutputChannel,
    InputChannel,
    OnNewMessageType,
    UserMessage,
)
from rasa.core.channels.rest import RestInput
from rasa.utils.endpoints import ClientResponseError, EndpointConfig

logger = logging.getLogger(__name__)


@dataclass
class _CallbackStreamState:
    """Bookkeeping for one active callback stream."""

    stream_id: Text
    delta_count: int = 0


class CallbackOutput(CollectingOutputChannel):
    @classmethod
    def name(cls) -> Text:
        return "callback"

    def __init__(
        self, endpoint: EndpointConfig, streaming_enabled: bool = False
    ) -> None:
        self.callback_endpoint = endpoint
        self._streaming_enabled = streaming_enabled
        self._stream: Optional[_CallbackStreamState] = None
        self._completed_stream_metadata: Dict[Text, Any] = {}
        self._callback_delivery_queue: asyncio.Queue[Dict[Text, Any]] = asyncio.Queue()
        self._callback_delivery_task: Optional[asyncio.Task[None]] = None
        super().__init__()

    async def _persist_message(self, message: Dict[Text, Any]) -> None:
        await super()._persist_message(message)

        self._enqueue_callback_delivery(message)

    def _enqueue_callback_delivery(self, message: Dict[Text, Any]) -> None:
        self._callback_delivery_queue.put_nowait(message.copy())
        self._ensure_callback_delivery_task()

    def _ensure_callback_delivery_task(self) -> None:
        if (
            self._callback_delivery_task is not None
            and not self._callback_delivery_task.done()
        ):
            return

        self._callback_delivery_task = asyncio.create_task(
            self._drain_callback_delivery_queue()
        )
        self._callback_delivery_task.add_done_callback(
            self._log_callback_delivery_task_error
        )

    async def _drain_callback_delivery_queue(self) -> None:
        while not self._callback_delivery_queue.empty():
            message = await self._callback_delivery_queue.get()
            try:
                await self._post_to_callback(message)
            finally:
                self._callback_delivery_queue.task_done()

    @staticmethod
    def _log_callback_delivery_task_error(task: asyncio.Task[None]) -> None:
        try:
            task.result()
        except asyncio.CancelledError:
            pass
        except Exception:
            logger.exception("Unexpected callback delivery task failure.")

    async def wait_for_callback_delivery(self) -> None:
        """Wait until all queued callback delivery attempts have finished."""
        await self._callback_delivery_queue.join()
        if self._callback_delivery_task is not None:
            await asyncio.shield(self._callback_delivery_task)

    async def _post_to_callback(self, message: Dict[Text, Any]) -> None:
        try:
            await self.callback_endpoint.request(
                "post", content_type="application/json", json=message
            )
        except ClientResponseError as e:
            logger.error(
                "Failed to send output message to callback. "
                "Status: {} Response: {}"
                "".format(e.status, e.text)
            )
        except (aiohttp.ClientError, asyncio.TimeoutError) as e:
            logger.error(
                "Failed to send output message to callback. Error: {}".format(e)
            )

    @property
    def supports_streaming(self) -> bool:
        """Whether this callback output should send discrete streaming events."""
        return self._streaming_enabled

    async def send_response_chunk_start(
        self,
        recipient_id: Text,
        **kwargs: Any,
    ) -> None:
        """Send a callback event that marks the start of a streamed response."""
        await super().send_response_chunk_start(recipient_id, **kwargs)
        if not self.supports_streaming:
            self._stream = None
            self._completed_stream_metadata = {}
            return

        self._stream = _CallbackStreamState(stream_id=uuid.uuid4().hex)
        self._completed_stream_metadata = {}
        await self._persist_message(
            {
                "type": "stream_start",
                "stream_id": self._stream.stream_id,
                "recipient_id": recipient_id,
            }
        )

    async def send_response_chunk(
        self,
        recipient_id: Text,
        chunk: Text,
        **kwargs: Any,
    ) -> None:
        """Send a streamed text delta as a discrete callback event."""
        if not self.supports_streaming:
            await super().send_response_chunk(recipient_id, chunk, **kwargs)
            return

        if self._stream is None:
            await self.send_response_chunk_start(recipient_id, **kwargs)

        if self._stream is None:
            return

        await super().send_response_chunk(recipient_id, chunk, **kwargs)
        await self._persist_message(
            {
                "type": "stream_delta",
                "stream_id": self._stream.stream_id,
                "recipient_id": recipient_id,
                "text": chunk,
                "index": self._stream.delta_count,
            }
        )
        self._stream.delta_count += 1

    async def send_response_chunk_end(
        self,
        recipient_id: Text,
        **kwargs: Any,
    ) -> None:
        """Send a callback event that marks the end of a streamed response."""
        await super().send_response_chunk_end(recipient_id, **kwargs)
        if not self.supports_streaming:
            return

        if self._stream is None:
            return

        await self._persist_message(
            {
                "type": "stream_end",
                "stream_id": self._stream.stream_id,
                "recipient_id": recipient_id,
            }
        )
        self._completed_stream_metadata = {
            "stream_id": self._stream.stream_id,
            "streamed": True,
            "stream_delta_count": self._stream.delta_count,
        }
        self._stream = None

    async def send_text_message(
        self,
        recipient_id: Text,
        text: Text,
        **kwargs: Any,
    ) -> None:
        """Send a text message, annotating it if it completes a stream."""
        streamed_message_metadata = self._metadata_for_completed_stream(text)
        for message_part in text.strip().split("\n\n"):
            message = self._message(recipient_id, text=message_part)
            message.update(streamed_message_metadata)
            await self._persist_message(message)

        if streamed_message_metadata:
            self._completed_stream_metadata = {}

    def _metadata_for_completed_stream(self, text: Text) -> Dict[Text, Any]:
        """Return metadata for a final text message that matches a completed stream."""
        if not self._completed_stream_metadata:
            return {}

        if not self._is_duplicate_of_last_streamed_response(text):
            return {}

        return self._completed_stream_metadata.copy()


class CallbackInput(RestInput):
    """A custom REST http input channel that responds using a callback server.

    Incoming messages are received through a REST interface. Responses
    are sent asynchronously by calling a configured external REST endpoint.
    """

    @classmethod
    def name(cls) -> Text:
        return "callback"

    @classmethod
    def from_credentials(cls, credentials: Optional[Dict[Text, Any]]) -> InputChannel:
        return cls(EndpointConfig.from_dict(credentials))

    def __init__(self, endpoint: EndpointConfig) -> None:
        self.callback_endpoint = endpoint

    def blueprint(self, on_new_message: OnNewMessageType) -> Blueprint:
        callback_webhook = Blueprint("callback_webhook", __name__)

        @callback_webhook.route("/", methods=["GET"])
        async def health(_: Request) -> HTTPResponse:
            return response.json({"status": "ok"})

        @callback_webhook.route("/webhook", methods=["POST"])
        async def webhook(request: Request) -> HTTPResponse:
            sender_id = await self._extract_sender(request)
            text = self._extract_message(request)
            metadata = self.get_metadata(request)
            should_use_stream = rasa.utils.endpoints.bool_arg(
                request, "stream", default=False
            )

            collector = self.get_output_channel(should_use_stream)
            await on_new_message(
                UserMessage(
                    text,
                    collector,
                    sender_id,
                    input_channel=self.name(),
                    metadata=metadata,
                    headers=request.headers,
                )
            )
            return response.text("success")

        return callback_webhook

    def get_output_channel(
        self, streaming_enabled: bool = False
    ) -> CollectingOutputChannel:
        return CallbackOutput(self.callback_endpoint, streaming_enabled)
